// Example: typed streaming decode with extras opt-in
ctx := context.Background()
r := bytes.NewReader(streamBytes)
var out MyResponse
meta, err := go_sdk.DecodeStream[MyResponse](ctx, r, go_sdk.WithExtras(true))
if err != nil {
  return err
}
// meta contains meta.version and rawExtras if any

// Fallback example: dynamic decode when version unknown
mapOut, meta, err := go_sdk.DecodeStreamDynamic(ctx, r)
if err == nil {
  // inspect meta.version and mapOut keys
}
